query CarComponentsQuery(
  $token: String!
  $priceConfigInput: PriceConfigurationInput
  $locale: String!
) {
  carByToken(token: $token) {
    configurationByToken(token: $token) {
      token {
        short
      }
      components {
        tags
        code
        type
        content(locale: $locale) {
          displayName {
            value
          }
          description {
            value
          }
          ... on OptionContent {
            group {
              value
              formatted
            }
            categoryPlacement {
              path {
                displayName {
                  value
                }
              }
            }
          }
          ... on PackageContent {
            group {
              value
              formatted
            }
          }
          ... on ColourContent {
            group {
              value
              formatted
            }
            colorType {
              formatted
            }
          }
          ... on UpholsteryContent {
            group {
              value
              formatted
            }
            upholsteryMaterial {
              formatted
            }
          }
          image {
            url
          }
        }
        requires {
          content(locale: $locale) {
            description {
              value
            }
            displayName {
              value
            }
            image {
              url
            }
          }
          code
        }
        inConfiguration {
          selected
          included
          active
        }
        configurations {
          appliedChange {
            priceSummary(priceConfigInput: $priceConfigInput) {
              all {
                relativeBasePriceInclTax {
                  display
                }
                priceBreakdownPriceInclTax {
                  display
                }
              }
            }
          }
        }
        alternativeCodes
        visible
        requiresExclusively {
          content(locale: $locale) {
            description {
              value
            }
            displayName {
              value
            }
            image {
              url
            }
          }
        }
      }
    }
    commercialModelYear {
      name
      structureWeekFrom
    }
    visualizations(marketOrLocale: $locale) {
      views {
        exterior {
          standardizedSideView {
            sizes {
              default {
                url
              }
            }
          }
        }
      }
    }
  }
}

query CarsByPolicy(
  $policy: String!
  $locale: String!
  $priceConfigInput: PriceConfigurationInput
  $clientType: String!
) {
  carsByPolicy(policy: $policy, clientType: $clientType) {
    cars {
      priceListDisplayName(locale: $locale)
      priceSummary(priceConfigInput: $priceConfigInput) {
        price {
          display
          amount
        }
      }
      model(locale: $locale) {
        displayName {
          value
        }
      }
      salesVersion: trim(locale: $locale) {
        displayName {
          value
        }
        description {
          value
        }
      }
      theme: trimFamily(locale: $locale) {
        displayName {
          value
        }
        description {
          value
        }
      }
      engine {
        content(locale: $locale) {
          fuelType {
            formatted
            value
          }
          engineType {
            formatted
            value
          }
        }
      }
      driveline {
        content(locale: $locale) {
          driveType {
            formatted
            value
          }
          transmissionType {
            formatted
          }
          gearboxFullName {
            value
          }
        }
      }
      pno {
        pno12
      }
      carKeyExpanded {
        carType
        engine
        salesVersion
        gearbox
        steering
        marketingCode
        specMarket
        body
        modelYear
      }
      visualizations(marketOrLocale: $locale) {
        views {
          exterior {
            studio {
              left {
                sizes {
                  default {
                    url
                  }
                }
              }
            }
          }
        }
      }
      technicalData(locale: $locale) {
        all {
          key
          label
          formatted
        }
      }
      configuration {
        token {
          short
        }
      }
    }
  }
}

