query PreConfigValidation(
  $policy: String!
  $specification: CarConfigurationSpecification!
) {
  carConfigurationBySpecification(
    policy: $policy
    specification: $specification
  ) {
    appliedChange {
      componentsAdded {
        globalName
        code
        type
      }
      componentsRemoved {
        code
        globalName
        type
      }
    }
  }
}

query PriceBreakdownQuery(
  $token: String!
  $priceConfigInput: PriceConfigurationInput
) {
  carByToken(token: $token) {
    priceSummary(priceConfigInput: $priceConfigInput) {
      totalPrice {
        display
      }
      totalPriceWithoutTax {
        display
      }
      taxes {
        informational {
          name
          vatRate
          vatPosition
          price {
            display
          }
        }
        acquisition {
          name
          vatRate
          vatPosition
          price {
            display
          }
        }
      }
      breakDown {
        color {
          code
          type
          price {
            display
            amount
          }
        }
        upholstery {
          code
          type
          price {
            display
            amount
          }
        }
        options {
          code
          type
          price {
            display
            amount
          }
        }
        packages {
          code
          type
          price {
            display
            amount
          }
        }
      }
    }
  }
}

query PriceQuery($token: String!, $priceConfigInput: PriceConfigurationInput) {
  carByToken(token: $token) {
    priceSummary(priceConfigInput: $priceConfigInput) {
      totalPrice {
        display
      }
    }
  }
}
